function aid(int $n):string{return '00000000-0000-4000-8000-'.str_pad((string)$n,12,'0',STR_PAD_LEFT);}
function adb():PDO{return new PDO('mysql:host=127.0.0.1;port=33081;dbname=kios_development','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}
function ac(bool $ok):void{if(!$ok)throw new RuntimeException('assertion');}
function aauth(int $id,?Closure $hook=null):AuthenticatedUserProvider{return new class(aid($id),$hook) implements AuthenticatedUserProvider {private int $calls=0;public function __construct(private string $id,private ?Closure $hook){}public function currentUserId():?string{if($this->hook)($this->hook)(++$this->calls);return $this->id;}};}
function adeny(callable $work):void{try{$work();}catch(DomainException|InvalidArgumentException $expected){return;}throw new RuntimeException('expected denial');}
function apdo(callable $work,string $state,?int $vendor=null):void{try{$work();}catch(PDOException $e){ac((string)$e->getCode()===$state&&($vendor===null||(int)$e->errorInfo[1]===$vendor));return;}throw new RuntimeException('expected database failure');}
function acase(string $name,callable $work):void{global $result;try{$work();$result['passed']++;$result['cases'][$name]='PASS';}catch(Throwable $e){$result['failed']++;$result['cases'][$name]=get_class($e).':'.$e->getCode().':'.$e->getMessage();}}
function arows(PDO $db):array{$all=[];foreach($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $t){$rows=$db->query('SELECT * FROM `'.$t.'`')->fetchAll(PDO::FETCH_ASSOC);$rows=array_map(fn($r)=>hash('sha256',json_encode(array_map(fn($v)=>is_string($v)?['base64'=>base64_encode($v)]:$v,$r),JSON_THROW_ON_ERROR)),$rows);sort($rows);$all[$t]=$rows;}ksort($all);return $all;}
function adig(PDO $db):array{$r=arows($db);foreach($r as $t=>$rows)$r[$t]=['count'=>count($rows),'digest'=>hash('sha256',implode("\n",$rows))];return $r;}
function acmd(array $args):void{$p=proc_open($args,[0=>['pipe','r'],1=>['file','C:/m02a-command.out','a'],2=>['file','C:/m02a-command.err','a']],$pipes);if(!is_resource($p))throw new RuntimeException('command');fclose($pipes[0]);if(proc_close($p)!==0)throw new RuntimeException('command exit');}
function ainput(string $label='A',string $type='restaurant'):array{return ['business_name'=>'Synthetic business '.$label,'business_type'=>$type,'admin_contact'=>'synthetic-'.$label.'@example.invalid','outlet_name'=>'Synthetic outlet '.$label,'owner_name'=>'Synthetic owner '.$label,'owner_username'=>'synthetic-owner','opening_time'=>'08:00','closing_time'=>'22:00'];}
