acase('018 partial index migration detects interruption and restores exact populated binary-safe data',function()use(&$db){
    $before=adig($db);acmd(['C:/Mapped/Tools/mariadb/bin/mysqldump.exe','--no-defaults','--host=127.0.0.1','--port=33081','--user=root','--single-transaction','--hex-blob','--result-file=C:/m02a.sql','--databases','kios_development']);
    $sql=file_get_contents('C:/KiosB0/database/migrations/018_merchant_provisioning.sql');$db->exec(preg_split('/;\s*(?:\r?\n|$)/',$sql)[0]);
    apdo(fn()=>(new MigrationRunner($db))->apply('C:/KiosB0/database/migrations'),'42000',1061);ac(adig($db)===$before);
    $db=null;$root=new PDO('mysql:host=127.0.0.1;port=33081','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$root->exec('DROP DATABASE kios_development');
    acmd(['C:/Mapped/Tools/mariadb/bin/mysql.exe','--no-defaults','--host=127.0.0.1','--port=33081','--user=root','--execute=source C:/m02a.sql']);$db=adb();ac(adig($db)===$before);
    ac((new MigrationRunner($db))->apply('C:/KiosB0/database/migrations')===['018_merchant_provisioning.sql']);ac((new MigrationRunner($db))->apply('C:/KiosB0/database/migrations')===[]);
    $after=adig($db);foreach($before as $t=>$v)if($t!=='schema_migrations')ac($after[$t]===$v);
    file_put_contents('C:/Mapped/Results/m02a-recovery.json',json_encode(['status'=>'PASS','before'=>$before,'after'=>$after,'backupSha256'=>hash_file('sha256','C:/m02a.sql')],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));
});
